TITLE = "สังคารวสูตร"
SUB = "มัชฌิมนิกาย มัชฌิมปัณณาสก์ (MN 100) · นโม ๓ จบ และการตรัสรู้ของพระพุทธเจ้า"
EXPAND = {
    "mn100:10.6": "na kho āḷārasseva kālāmassa atthi vīriyaṁ, mayhampatthi vīriyaṁ;",
    "mn100:10.7": "na kho āḷārasseva kālāmassa atthi sati, mayhampatthi sati;",
    "mn100:10.8": "na kho āḷārasseva kālāmassa atthi samādhi, mayhampatthi samādhi;",
    "mn100:11.16": "na kho rāmasseva ahosi vīriyaṁ, mayhampatthi vīriyaṁ;",
    "mn100:11.17": "na kho rāmasseva ahosi sati, mayhampatthi sati;",
    "mn100:11.18": "na kho rāmasseva ahosi samādhi, mayhampatthi samādhi;",
    "mn100:31-33.1": "So kho ahaṁ, bhāradvāja, oḷārikaṁ āhāraṁ āhāretvā balaṁ gahetvā vivicceva kāmehi vivicca akusalehi dhammehi savitakkaṁ savicāraṁ vivekajaṁ pītisukhaṁ paṭhamaṁ jhānaṁ upasampajja vihāsiṁ.",
    "mn100:31-33.2": "Vitakkavicārānaṁ vūpasamā ajjhattaṁ sampasādanaṁ cetaso ekodibhāvaṁ avitakkaṁ avicāraṁ samādhijaṁ pītisukhaṁ dutiyaṁ jhānaṁ upasampajja vihāsiṁ.",
    "mn100:31-33.3": "pītiyā ca virāgā upekkhako ca vihāsiṁ sato ca sampajāno sukhañca kāyena paṭisaṁvedesiṁ, yaṁ taṁ ariyā ācikkhanti ‘upekkhako satimā sukhavihārī’ti tatiyaṁ jhānaṁ upasampajja vihāsiṁ.",
    "mn100:34.2": "So anekavihitaṁ pubbenivāsaṁ anussarāmi, seyyathidaṁ—ekampi jātiṁ dvepi jātiyo …pe… iti sākāraṁ sauddesaṁ anekavihitaṁ pubbenivāsaṁ anussarāmi.",
    "mn100:36-38.2": "So dibbena cakkhunā visuddhena atikkantamānusakena satte passāmi cavamāne upapajjamāne hīne paṇīte suvaṇṇe dubbaṇṇe sugate duggate yathākammūpage satte pajānāmi.",
}
TH = {
    "1": "ข้าพเจ้าได้ฟังมาอย่างนี้ สมัยหนึ่ง พระผู้มีพระภาคเจ้าเสด็จจาริกในแคว้นโกศล พร้อมภิกษุสงฆ์หมู่ใหญ่",
    "2": "ครั้งนั้น พราหมณีชื่อธนัญชานีอยู่ที่นิคมชื่อจัณฑลกัปปะ มีความเลื่อมใสในพระพุทธ พระธรรม พระสงฆ์ นางสะดุดพลาดล้ม จึงเปล่งอุทาน ๓ ครั้งว่า นะโม ตัสสะ ภะคะวะโต อะระหะโต สัมมาสัมพุทธัสสะ (ขอนอบน้อมแด่พระผู้มีพระภาคเจ้า พระอรหันต์ ผู้ตรัสรู้ชอบได้เอง) ๓ ครั้ง",
    "3": "ครั้งนั้น สังคารวมาณพอยู่ที่จัณฑลกัปปะ จบไตรเพท ได้ยินนางธนัญชานีกล่าวอย่างนั้น จึงตำหนินางว่า ธนัญชานีผู้เสื่อมทรามเอ๋ย มีพราหมณ์ผู้จบไตรเพทตั้งมากมาย เธอกลับยกย่องสมณะโล้นหัวนั้น นางตอบว่า พ่อหนุ่ม เธอยังไม่รู้จักศีลและปัญญาของพระองค์ ถ้ารู้จักแล้ว จะไม่คิดแม้แต่จะพูดว่าร้าย สังคารวมาณพจึงว่า ถ้าอย่างนั้น เมื่อพระสมณโคดมมาถึงจัณฑลกัปปะ จงบอกฉันด้วย",
    "4": "พระผู้มีพระภาคเจ้าเสด็จจาริกไปตามลำดับจนถึงจัณฑลกัปปะ ประทับอยู่ที่อัมพวันของพราหมณ์โตเทยยะ",
    "5": "นางธนัญชานีทราบข่าว จึงบอกสังคารวมาณพ สังคารวมาณพเข้าเฝ้าพระผู้มีพระภาคเจ้า สนทนาปราศรัยแล้วนั่งลง ทูลถามว่า",
    "6": "ข้าแต่พระโคดม สมณพราหมณ์บางพวกอ้างว่าบรรลุถึงที่สุดแห่งความรู้ยิ่งในปัจจุบันและถึงพรหมจรรย์ขั้นต้น ในพวกเหล่านั้น พวกไหนอ้างได้จริง",
    "7": "พระผู้มีพระภาคเจ้าตรัสว่า ภารทวาชะ ผู้ที่อ้างเช่นนั้นมี ๓ พวก คือ พวกที่อ้างเพราะฟังตามกันมา (อย่างพราหมณ์จบไตรเพท) พวกที่อ้างเพราะเพียงศรัทธา (อย่างนักตรรกะ) และพวกที่รู้ธรรมด้วยตนเองในธรรมที่ไม่เคยได้ยินมาก่อน ใน ๓ พวกนี้ พวกที่รู้ด้วยตนเองต่างหากจึงอ้างได้ถูกต้อง",
    "8": "ภารทวาชะ ข้อที่พวกที่รู้ธรรมด้วยตนเองอ้างได้ถูกต้อง ควรเข้าใจด้วยวิธีนี้",
    "9": "ภารทวาชะ ก่อนตรัสรู้ ตอนเป็นโพธิสัตว์ เราได้คิดว่า การอยู่ครองเรือนคับแคบ เป็นทางมาแห่งธุลี การบรรพชาเป็นที่โล่ง เราจึงโกนผม โกนหนวด นุ่งห่มผ้ากาสายะ ออกบวช แสวงหาว่าอะไรเป็นกุศล เข้าไปหาอาฬารดาบสกาลามะ ขอบวชเรียนในธรรมวินัยของท่าน เรียนได้เร็ว จนถึงขั้นกล่าวได้ว่า ญาณและความแก่กล้า เราก็คิดว่า อาฬารดาบสไม่ได้ประกาศธรรมนี้ด้วยศรัทธาเท่านั้น ท่านรู้เห็นอยู่จริง",
    "10": "เราจึงถามอาฬารดาบสว่า ท่านรู้เห็นธรรมนี้อย่างไร ท่านบอกอากิญจัญญายตนะ เราคิดว่า เราก็มีศรัทธา วิริยะ สติ สมาธิ ปัญญาเหมือนท่าน จึงเพียรจนรู้แจ้งธรรมนั้น อาฬารดาบสจึงเชิญเราเป็นอาจารย์ร่วม เราคิดว่า ธรรมนี้ไม่เป็นไปเพื่อเบื่อหน่าย คลายกำหนัด ดับ สงบ รู้ยิ่ง ตรัสรู้ นิพพาน จึงเบื่อหน่ายแล้วจากไป",
    "11": "เราเข้าไปหาอุทกดาบสรามบุตร ขอบวชเรียน ท่านบอกเนวสัญญานาสัญญายตนะ เรารู้แจ้งได้เช่นกัน",
    "12": "อุทกดาบสเชิญเราเป็นอาจารย์แทนตน เราคิดว่า ธรรมนี้ก็ไม่เป็นไปเพื่อนิพพาน จึงเบื่อหน่ายแล้วจากไป",
    "13": "เราแสวงหาว่าอะไรเป็นกุศลต่อไป ถึงอุรุเวลาเสนานิคม ได้เห็นภูมิภาคที่น่ารื่นรมย์ แม่น้ำเนรัญชราไหลใส จึงคิดว่า ที่นี่เหมาะแก่การตั้งความเพียรของกุลบุตร จึงนั่งตั้งความเพียร ณ ที่นั้น",
    "14": "ภารทวาชะ อุปมา ๓ ข้อที่ไม่เคยมีมาก่อน ได้ปรากฏแก่เรา ข้อที่หนึ่ง เหมือนไม้เปียกมียาง จุ่มอยู่ในน้ำ คนนำไม้สีไฟมาสี ก็ไม่อาจติดไฟได้ ฉันใด สมณะหรือพราหมณ์ที่ยังไม่สงัดกายใจจากกาม ก็ไม่อาจบรรลุญาณทัสสนะอันยอดเยี่ยมได้ ฉันนั้น",
    "15": "ข้อที่สอง เหมือนไม้เปียกมียาง วางบนบก คนสีไฟก็ไม่อาจติดไฟได้ ฉันใด ผู้ที่สงัดกายแล้วแต่ใจยังไม่สงัดจากกาม ก็ไม่อาจบรรลุได้ ฉันนั้น",
    "16": "ข้อที่สาม เหมือนไม้แห้งสนิท วางบนบก คนสีไฟย่อมติดไฟได้ ฉันใด ผู้ที่สงัดทั้งกายและใจจากกาม ย่อมบรรลุญาณทัสสนะอันยอดเยี่ยมได้ ฉันนั้น",
    "17": "เราคิดว่า จะกัดฟันด้วยฟัน กดเพดานด้วยลิ้น ข่มจิตด้วยจิต ให้แน่วแน่ เราทำอย่างนั้น เหงื่อไหลจากรักแร้ เหมือนบุรุษแข็งแรงจับศีรษะบุรุษอ่อนแอกว่ากดลง แต่ความเพียรก็ไม่ท้อถอย สติตั้งมั่น",
    "18": "เราคิดว่า จะเจริญฌานแบบกลั้นลมหายใจ จึงกลั้นลมหายใจทางปากและจมูก ลมพลุ่งออกทางหู เสียงดังเหมือนเสียงสูบของช่างทอง แต่ความเพียรไม่ท้อถอย",
    "19": "เรากลั้นลมหายใจทางปาก จมูก และหู ลมเสียดแทงศีรษะ เหมือนบุรุษแข็งแรงเจาะศีรษะด้วยเหล็กแหลม แต่ความเพียรไม่ท้อถอย",
    "20": "ลมเสียดแทงศีรษะอย่างแรง เหมือนบุรุษแข็งแรงรัดศีรษะด้วยเชือกหนังแข็ง แต่ความเพียรไม่ท้อถอย",
    "21": "ลมเสียดแทงท้อง เหมือนคนฆ่าโคหรือลูกมือใช้มีดคมผ่าท้อง แต่ความเพียรไม่ท้อถอย",
    "22": "ร่างกายร้อนจัด เหมือนบุรุษแข็งแรงสองคนจับบุรุษอ่อนแอกว่า ย่างบนหลุมถ่านไฟ แต่ความเพียรไม่ท้อถอย",
    "23": "เทวดาเห็นเข้า บางพวกว่า พระสมณโคดมสิ้นแล้ว บางพวกว่า ยังไม่สิ้นแต่กำลังจะสิ้น บางพวกว่า พระองค์เป็นพระอรหันต์ การอยู่อย่างนี้เป็นการอยู่ของพระอรหันต์",
    "24": "เราคิดว่า จะงดอาหารโดยสิ้นเชิง เทวดามาบอกว่า ถ้างดอาหาร เราจะให้โอชะทิพย์ทางรูขุมขนเลี้ยงไว้ เราคิดว่า ถ้าเราอ้างว่างดอาหารสิ้นเชิงแต่เทวดาให้โอชะ นั่นก็เป็นมุสา จึงปฏิเสธเทวดาเหล่านั้น",
    "25": "เราคิดว่า จะฉันอาหารทีละน้อย ๆ คือ ซุปถั่วหรือซุปถั่วเขียวกำมือเดียว ร่างกายจึงผ่ายผอม อวัยวะน้อยใหญ่เหมือนเถาไม้ เนื้อสะโพกเหมือนกีบอูฐ กระดูกสันหลังนูนเหมือนลูกประคำ ซี่โครงเหมือนกลอนเรือนเก่า ดวงตาลึกเหมือนดาวในบ่อลึก ผิวหนังเหี่ยวเหมือนน้ำเต้าขมถูกแดดเผา เมื่อเราจะจับผิวท้องก็จับได้กระดูกสันหลัง เมื่อจะถ่ายปัสสาวะก็ล้มคว่ำลงตรงนั้น เราจึงลูบตัวเพื่อคลายความทุกข์ ขนร่วงหล่นไปมาก",
    "26": "มนุษย์ที่เห็นเข้าบางพวกว่า พระสมณโคดมดำคล้ำ บางพวกว่า ไม่ดำ เป็นสีคล้ำ บางพวกว่า ไม่ดำไม่คล้ำ ผิวพระสมณโคดมเป็นสีเหมือนปลามังกุร ผิวพรรณบริสุทธิ์ผ่องใสเสียไปมากเพราะฉันอาหารน้อย",
    "27": "เราคิดว่า สมณพราหมณ์ในอดีต อนาคต และปัจจุบัน ที่เสวยทุกข์จากการบำเพ็ญตบะอย่างแรงกล้า ก็ไม่เกินกว่านี้ แต่เราก็ยังไม่บรรลุญาณทัสสนะอันยอดเยี่ยม จึงคิดว่า ทางตรัสรู้จะต้องมีทางอื่น",
    "28": "เราระลึกได้ว่า สมัยเป็นเด็ก นั่งอยู่ใต้ร่มหว้าในงานของพระบิดา ได้บรรลุปฐมฌานอันสงัดจากกามและอกุศลธรรม นั่นแหละคือทางตรัสรู้",
    "29": "เราคิดว่า ทำไมเราจึงกลัวสุขนั้นซึ่งไม่ใช่กาม ไม่ใช่อกุศลธรรม เราจึงไม่กลัวสุขนั้น",
    "30": "เราคิดว่า ด้วยร่างกายที่ผ่ายผอมอย่างนี้ ไม่ง่ายที่จะบรรลุสุขนั้น จึงฉันอาหารหยาบคือข้าวสุกและขนมกุมมาส ภิกษุปัญจวัคคีย์ที่คอยอุปัฏฐากอยู่คิดว่า พระสมณโคดมจะบรรลุธรรมแล้วบอกเรา พอเห็นเราฉันอาหาร จึงทิ้งเราไปว่า พระสมณโคดมเป็นคนมักมาก คลายความเพียรแล้ว",
    "31-33": "เราฉันอาหารหยาบจนมีกำลังแล้ว สงัดจากกามและอกุศลธรรม บรรลุปฐมฌาน ทุติยฌาน ตติยฌาน และจตุตถฌาน ตามลำดับ",
    "34": "เมื่อจิตตั้งมั่นบริสุทธิ์แล้ว เราระลึกชาติก่อนได้หลายชาติ ว่าเราเคยเกิดชื่ออย่างนั้น ตระกูลอย่างนั้น ไปเกิดในภพนั้น ๆ",
    "35": "นี่คือวิชชาที่หนึ่งที่เราได้ในยามต้นแห่งราตรี อวิชชาถูกกำจัด วิชชาเกิดขึ้น ความมืดถูกกำจัด แสงสว่างเกิดขึ้น",
    "36-38": "เมื่อจิตตั้งมั่นบริสุทธิ์แล้ว เราเห็นสัตว์ด้วยทิพจักษุ เห็นสัตว์จุติและเกิดตามกรรมของตน นี่คือวิชชาที่สองที่เราได้ในยามกลางแห่งราตรี",
    "39": "เมื่อจิตตั้งมั่นบริสุทธิ์แล้ว เรารู้ชัดตามความเป็นจริงว่า นี่คือทุกข์ นี่คือเหตุเกิดทุกข์ นี่คือความดับทุกข์ นี่คือทางดับทุกข์ นี่คืออาสวะ นี่คือเหตุเกิดอาสวะ นี่คือความดับอาสวะ นี่คือทางดับอาสวะ",
    "40": "เมื่อรู้เห็นอย่างนี้ จิตก็พ้นจากกามาสวะ ภวาสวะ และอวิชชาสวะ เกิดญาณว่าหลุดพ้นแล้ว รู้ชัดว่า การเกิดสิ้นแล้ว พรหมจรรย์อยู่จบแล้ว สิ่งที่ควรทำได้ทำเสร็จแล้ว ไม่มีอะไรต้องทำเพื่อความเป็นอย่างนี้อีก",
    "41": "นี่คือวิชชาที่สามที่เราได้ในยามสุดท้ายแห่งราตรี อวิชชาถูกกำจัด วิชชาเกิดขึ้น ความมืดถูกกำจัด แสงสว่างเกิดขึ้น",
    "42": "สังคารวมาณพทูลถามว่า เทวดามีจริงหรือ พระผู้มีพระภาคเจ้าตรัสว่า เรารู้โดยฐานะว่าเทวดามีจริง สังคารวมาณพถามว่า ทำไมพระองค์ไม่ตอบตรง ๆ ว่ามี พระองค์ตรัสว่า โลกสมมติกันว่าเทวดามีจริง",
    "43": "สังคารวมาณพทูลว่า แจ่มแจ้งนัก พระโคดม เปรียบเหมือนหงายของที่คว่ำ เปิดของที่ปิด บอกทางแก่คนหลงทาง ส่องประทีปในที่มืด ข้าพระองค์ขอถึงพระโคดม พระธรรม และพระสงฆ์เป็นสรณะ ขอพระองค์ทรงจำข้าพระองค์ว่าเป็นอุบาสก ผู้ถึงสรณะตลอดชีวิต ตั้งแต่วันนี้เป็นต้นไป (จบสังคารวสูตรที่ ๑๐)",
    "44": "หัวข้อประจำวรรค: พราหมายุสูตร เสลสูตร อัสสลายนสูตร โฆฏมุขสูตร จังกีสูตร เอสุกาสูตร ธนัญชานีสูตร วาเสฏฐสูตร สุภสูตร และสังคารวสูตร",
    "45": "หัวข้อรวมหมวด: คหปติวรรค ภิกขุวรรค ปริพาชกวรรค ราชวรรค และพราหมณวรรค รวมเป็นมัชฌิมปัณณาสก์",
}
